def to_seconds(val):
    """Normalizes input to seconds."""
    return float(val)

def top_k(records, k, key):
    """Returns top k records based on key."""
    return sorted(records, key=lambda x: x[key], reverse=True)[:k]

def count_lines(text):
    """Counts lines in a string."""
    return len(text.splitlines())
