import json
import corelib.utils as corelib

def run(data_path, out_path):
    with open(data_path, 'r') as f:
        data = json.load(f)

    # 1. timeoutsSec
    timeouts = [corelib.to_seconds(v) for v in data['timeoutsSec']['values']]

    # 2. topIds
    top_records = corelib.top_k(
        data['topIds']['records'], 
        data['topIds']['k'], 
        data['topIds']['key']
    )
    top_ids = sorted([r['id'] for r in top_records])

    # 3. lineCounts
    line_counts = [corelib.count_lines(t) for t in data['lineCounts']['texts']]

    result = {
        "timeoutsSec": timeouts,
        "topIds": top_ids,
        "lineCounts": line_counts
    }

    with open(out_path, 'w') as f:
        json.dump(result, f)
